#!/usr/bin/env bash

[ -r /etc/os-release ] || { echo "ERRO: sistema DEB-like nao identificado." >&2; exit 2; }
. /etc/os-release
case "${ID:-} ${ID_LIKE:-}" in *debian*|*ubuntu*) ;; *) echo "ERRO: audit exclusivo para Debian-like." >&2; exit 2 ;; esac

# 158 controles alinhados ao baseline aprovado 03_Hardening_2026_DEBLIKE.xlsx.
# Os IDs excluidos por decisao do cliente permanecem como lacunas e nao devem
# ser renumerados.
run_item() {
  local id="$1" title="$2" severity="$3" cmd="$4" expect="$5"
  local output rc result

  output=$(LC_ALL=C bash -c "$cmd" 2>&1)
  rc=$?
  if printf '%s\n' "$output" | grep -Pq -- "$expect"; then
    result=PASS
    TOTAL_PASS=$((TOTAL_PASS + 1))
  else
    result=FAIL
    TOTAL_FAIL=$((TOTAL_FAIL + 1))
  fi
  printf '%s,%s,%s,%s\n' "$id" "$title" "$severity" "$result"

  if [[ ${AUDIT_DEBUG:-0} == 1 ]]; then
    printf 'cmd: %s\nexpect: %s\nrc: %s\noutput:\n%s\n' "$cmd" "$expect" "$rc" "$output" >&2
  fi
}

TOTAL_PASS=0
TOTAL_FAIL=0
printf 'ID,NOME,CRITICIDADE,RESULTADO\n'
run_item 2 'Bloqueio squashfs' Baixa 'if modinfo squashfs >/dev/null 2>&1; then if modinfo squashfs >/dev/null 2>&1; then if modinfo squashfs >/dev/null 2>&1; then ( ! modinfo squashfs >/dev/null 2>&1 || { modprobe -n -v squashfs 2>/dev/null | grep -Eq '"'"'^install[[:space:]]+(/usr)?/bin/(true|false)([[:space:]]|$)'"'"' && ! lsmod | awk '"'"'{print $1}'"'"' | grep -qx squashfs; } ) && echo PASS || echo NA; else echo NA; fi && echo PASS || echo NA; else echo NA; fi && echo PASS || echo NA; else echo NA; fi' '(?i)^\s*(PASS|NA)\s*$'
